/* eslint-disable @typescript-eslint/no-unused-expressions */

import Float32Array = require( '@stdlib/array/float32' );
import Float64Array = require( '@stdlib/array/float64' );
import Complex64 = require( '@stdlib/complex/float32/ctor' );
import Complex128 = require( '@stdlib/complex/float64/ctor' );
import realf = require( '@stdlib/complex/float32/real' );
import imagf = require( '@stdlib/complex/float32/imag' );
import real = require( '@stdlib/complex/float64/real' );
import imag = require( '@stdlib/complex/float64/imag' );
import reinterpret64 = require( '@stdlib/strided/base/reinterpret-complex64' );
import reinterpret128 = require( '@stdlib/strided/base/reinterpret-complex128' );
import complexArrayFactory = require( './index' );


// TESTS //

// The function returns a constructor function...
{
	complexArrayFactory( 'complex64', Float32Array, Complex64, realf, imagf, reinterpret64 ); // $ExpectType ComplexTypedArrayConstructor<Complex64>
	complexArrayFactory( 'complex128', Float64Array, Complex128, real, imag, reinterpret128 ); // $ExpectType ComplexTypedArrayConstructor<Complex128>
}

// The compiler throws an error if the function is provided a first argument which is not a string...
{
	complexArrayFactory( 5, Float32Array, Complex64, realf, imagf, reinterpret64 ); // $ExpectError
	complexArrayFactory( true, Float32Array, Complex64, realf, imagf, reinterpret64 ); // $ExpectError
	complexArrayFactory( null, Float32Array, Complex64, realf, imagf, reinterpret64 ); // $ExpectError
	complexArrayFactory( [], Float32Array, Complex64, realf, imagf, reinterpret64 ); // $ExpectError
	complexArrayFactory( {}, Float32Array, Complex64, realf, imagf, reinterpret64 ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not a function...
{
	complexArrayFactory( 'complex64', 5, Complex64, realf, imagf, reinterpret64 ); // $ExpectError
	complexArrayFactory( 'complex64', 'abc', Complex64, realf, imagf, reinterpret64 ); // $ExpectError
	complexArrayFactory( 'complex64', true, Complex64, realf, imagf, reinterpret64 ); // $ExpectError
	complexArrayFactory( 'complex64', null, Complex64, realf, imagf, reinterpret64 ); // $ExpectError
	complexArrayFactory( 'complex64', [], Complex64, realf, imagf, reinterpret64 ); // $ExpectError
}

// The compiler throws an error if the function is provided a third argument which is not a constructor...
{
	complexArrayFactory( 'complex64', Float32Array, 5, realf, imagf, reinterpret64 ); // $ExpectError
	complexArrayFactory( 'complex64', Float32Array, 'abc', realf, imagf, reinterpret64 ); // $ExpectError
	complexArrayFactory( 'complex64', Float32Array, true, realf, imagf, reinterpret64 ); // $ExpectError
	complexArrayFactory( 'complex64', Float32Array, null, realf, imagf, reinterpret64 ); // $ExpectError
	complexArrayFactory( 'complex64', Float32Array, [], realf, imagf, reinterpret64 ); // $ExpectError
}

// The compiler throws an error if the function is provided a fourth argument which is not a function...
{
	complexArrayFactory( 'complex64', Float32Array, Complex64, 5, imagf, reinterpret64 ); // $ExpectError
	complexArrayFactory( 'complex64', Float32Array, Complex64, 'abc', imagf, reinterpret64 ); // $ExpectError
	complexArrayFactory( 'complex64', Float32Array, Complex64, true, imagf, reinterpret64 ); // $ExpectError
	complexArrayFactory( 'complex64', Float32Array, Complex64, null, imagf, reinterpret64 ); // $ExpectError
	complexArrayFactory( 'complex64', Float32Array, Complex64, [], imagf, reinterpret64 ); // $ExpectError
}

// The compiler throws an error if the function is provided a fifth argument which is not a function...
{
	complexArrayFactory( 'complex64', Float32Array, Complex64, realf, 5, reinterpret64 ); // $ExpectError
	complexArrayFactory( 'complex64', Float32Array, Complex64, realf, 'abc', reinterpret64 ); // $ExpectError
	complexArrayFactory( 'complex64', Float32Array, Complex64, realf, true, reinterpret64 ); // $ExpectError
	complexArrayFactory( 'complex64', Float32Array, Complex64, realf, null, reinterpret64 ); // $ExpectError
	complexArrayFactory( 'complex64', Float32Array, Complex64, realf, [], reinterpret64 ); // $ExpectError
}

// The compiler throws an error if the function is provided a sixth argument which is not a function...
{
	complexArrayFactory( 'complex64', Float32Array, Complex64, realf, imagf, 5 ); // $ExpectError
	complexArrayFactory( 'complex64', Float32Array, Complex64, realf, imagf, 'abc' ); // $ExpectError
	complexArrayFactory( 'complex64', Float32Array, Complex64, realf, imagf, true ); // $ExpectError
	complexArrayFactory( 'complex64', Float32Array, Complex64, realf, imagf, null ); // $ExpectError
	complexArrayFactory( 'complex64', Float32Array, Complex64, realf, imagf, [] ); // $ExpectError
}

// The compiler throws an error if the function is provided insufficient arguments...
{
	complexArrayFactory(); // $ExpectError
	complexArrayFactory( 'complex64' ); // $ExpectError
	complexArrayFactory( 'complex64', Float32Array ); // $ExpectError
	complexArrayFactory( 'complex64', Float32Array, Complex64 ); // $ExpectError
	complexArrayFactory( 'complex64', Float32Array, Complex64, realf ); // $ExpectError
	complexArrayFactory( 'complex64', Float32Array, Complex64, realf, imagf ); // $ExpectError
}
